CREATE TABLE operations_v1( id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, data_version TEXT NOT NULL, related_object_opr_infos TEXT NOT NULL, operation TEXT NOT NULL, operation_details TEXT NOT NULL, operation_state TEXT NOT NULL, operation_id TEXT NOT NULL, operater TEXT NOT NULL, operation_at BIGINT NOT NULL, why_failed TEXT NOT NULL );

CREATE TABLE user_todo_items( local_item_id TEXT PRIMARY KEY NOT NULL, remote_item_id TEXT NOT NULL, local_note_id TEXT NOT NULL, remote_note_id TEXT NOT NULL, user_id TEXT NOT NULL, body TEXT NOT NULL, original_content TEXT NOT NULL, original_content_save_at BIGINT NOT NULL, priority TEXT NOT NULL, done TEXT NOT NULL, closed TEXT NOT NULL, done_at BIGINT NOT NULL, doer_id TEXT NOT NULL, doer_username TEXT NOT NULL, doer_nickname TEXT NOT NULL, creater_id TEXT NOT NULL, creater_username TEXT NOT NULL, creater_nickname TEXT NOT NULL, notify_sms TEXT NOT NULL, notify_desktop_popup TEXT NOT NULL, notify_mobile_popup TEXT NOT NULL, notify_year BIGINT NOT NULL, notify_month BIGINT NOT NULL, notify_day BIGINT NOT NULL, notify_hour BIGINT NOT NULL, notify_minute BIGINT NOT NULL, notify_predefined_aheads TEXT NOT NULL, notify_custom_aheads TEXT NOT NULL, constant_pattern TEXT NOT NULL, constant_days_of_week BIGINT NOT NULL, constant_days_of_month BIGINT NOT NULL, constant_months_of_year BIGINT NOT NULL, constant_days_of_year TEXT NOT NULL, constant_dates TEXT NOT NULL, constant_year_from BIGINT NOT NULL, constant_month_from BIGINT NOT NULL, constant_day_from BIGINT NOT NULL, constant_year_to BIGINT NOT NULL, constant_month_to BIGINT NOT NULL, constant_day_to BIGINT NOT NULL, constant_over_pattern TEXT NOT NULL, constant_times BIGINT NOT NULL, constant_at TEXT NOT NULL, top_at BIGINT NOT NULL, sort BIGINT NOT NULL, create_at BIGINT NOT NULL, update_at BIGINT NOT NULL, delete_at BIGINT NOT NULL, next_remind_at BIGINT NOT NULL, text TEXT NOT NULL );

CREATE VIRTUAL TABLE search_user_todo_items_fts USING fts5( text, local_item_id UNINDEXED, body UNINDEXED, content = 'user_todo_items', tokenize = 'simple' );

CREATE TRIGGER user_todo_items_ai AFTER INSERT ON user_todo_items BEGIN INSERT INTO search_user_todo_items_fts(rowid, text, local_item_id, body) VALUES(new.rowid, new.text, new.local_item_id, new.body); END;

CREATE TRIGGER user_todo_items_au_text AFTER UPDATE OF text ON user_todo_items BEGIN INSERT INTO search_user_todo_items_fts(search_user_todo_items_fts, rowid, text, local_item_id, body) VALUES('delete', old.rowid, old.text, old.local_item_id, old.body); INSERT INTO search_user_todo_items_fts(rowid, text, local_item_id, body) VALUES(new.rowid, new.text, new.local_item_id, new.body); END;

CREATE TRIGGER user_todo_items_au_delete_at AFTER UPDATE OF delete_at ON user_todo_items BEGIN INSERT INTO search_user_todo_items_fts(search_user_todo_items_fts, rowid, text, local_item_id, body) VALUES('delete', old.rowid, old.text, old.local_item_id, old.body); END;

CREATE TRIGGER user_todo_items_ad AFTER DELETE ON user_todo_items BEGIN INSERT INTO search_user_todo_items_fts(search_user_todo_items_fts, rowid, text, local_item_id, body) VALUES('delete', old.rowid, old.text, old.local_item_id, old.body); END;
